"""The complete Svіtlytsia season. Content IDs are permanent save-game keys.

Mini-games represent the work between scenes, not purchasable relationship points.
Each working chapter has seven victories; chapter 16 is a conversation only.
"""

GAMES = {
    "bonus_match": "Bonus Match", "hidden_objects": "VPDK Детектив",
    "flappy": "Flappy Піксель", "pixel_drive": "Повний газ",
}


def option(key, label, response, delta, memory, **effects):
    return dict(id=key, label=label, response=response,
                delta=dict(zip(("trust", "closeness", "respect"), delta)), memory=memory, **effects)


def talk(key, chapter, title, lines, **extra):
    return dict(id=key, chapter=chapter, kind="dialogue", title=title, lines=lines, **extra)


def work(key, chapter, title, game, count):
    return dict(id=key, chapter=chapter, kind="game", title=title, game=game,
                games=[game], count=count, cta=f"Грати: {GAMES[game]}",
                description=f"{title}. Потрібно нових рівнів у {GAMES[game]}: {count}. Кожен рівень зараховується один раз. Проходження наперед зберігаються для наступних завдань цієї гри.")


