CHAPTERS = []
STEPS = []
# Four existing driving tracks and twelve flights are mandatory across all acts.
# Every working chapter still costs seven unique clears, within the live catalogs.
DRIVE_MISSIONS = {5: "Привезти коробку листів Ніни", 11: "Доставити матеріали для перевірки ремонту",
                  18: "Привезти інструменти сусідам", 23: "Доставити запрошення на відкриття"}
FLIGHT_MISSIONS = {4: "Оглянути підступи до майстерні", 8: "Перевірити шлях над дахами",
                   12: "Доправити звістку Ніні", 15: "Знайти шлях до архіву",
                   20: "Оглянути місце для саду", 24: "Перевірити Світлицю перед відкриттям"}
for n, title, summary, opening, evidence, jobs, choices, closing, found_title, found_text in EPISODES:
    CHAPTERS.append(dict(id=n, title=title, summary=summary))
    prefix = f"c{n:02d}"
    STEPS.append(talk(prefix + "_arrival", n, title, opening))
    if jobs:
        primary = "pixel_drive" if n in DRIVE_MISSIONS else "flappy" if n in FLIGHT_MISSIONS else "bonus_match"
        preparation_count = 1 if primary == "pixel_drive" else 2
        investigation_count = 2 if n % 2 == 0 else 3
        preparation_title = DRIVE_MISSIONS.get(n, FLIGHT_MISSIONS.get(n, jobs[0]))
        STEPS.append(work(prefix + "_prepare", n, preparation_title, primary, preparation_count))
        STEPS.append(work(prefix + "_investigate", n, jobs[1], "hidden_objects", investigation_count))
    STEPS.append(talk(prefix + "_evidence", n, "Перевірені сліди", evidence))
    if jobs:
        STEPS.append(work(prefix + "_finish", n, jobs[2], "bonus_match", 7 - preparation_count - investigation_count))
    project = {6: ("workbench", "Відновити майстерню", 160),
               13: ("ceiling", "Повернути кімнаті тепло", 300),
               22: ("roof_garden", "Облаштувати сад на даху", 450)}.get(n)
    if project:
        item, name, price = project
        STEPS.append(dict(id=prefix + "_decorate", chapter=n, kind="decorate", item=item,
                          title=name, description=f"Зібраних матеріалів достатньо. Заверши облаштування за {price} пір’їнок.", cta="Облаштувати"))
    if choices:
        STEPS.append(talk(prefix + "_choice", n, title, [evidence[-1]], choices=choices))
    STEPS.append(talk(prefix + "_close", n, title, closing, chapter_end=True,
                      gold=0 if n == 16 else 1,
                      discovery=dict(id=prefix, title=found_title, text=found_text)))


